// Generates design/REGISTRY.md from design/pages.json.
import { readFile, writeFile } from 'node:fs/promises';

const { pages } = JSON.parse(await readFile(new URL('./pages.json', import.meta.url), 'utf8'));
const dash = (v) => v ?? '—';
const rows = pages.map((p) =>
  `| \`${p.id}\` | ${p.name} | ${p.features.join(', ')} | ${p.phase} | ${dash(p.template)} | ${dash(p.source)} | ${dash(p.license)} | ${p.status} |`);
const md = [
  '<!-- GENERATED by design/build-registry.mjs from design/pages.json. Do not edit by hand. -->',
  '# Page registry',
  '',
  'No page is built without an **Approved** template here (UI-GATE, D-016).',
  '',
  '| ID | Page | Features | Phase | Template | Source | Licence | Status |',
  '|---|---|---|---|---|---|---|---|',
  ...rows,
  '',
].join('\n');
await writeFile(new URL('./REGISTRY.md', import.meta.url), md);
console.log(`REGISTRY.md written, ${pages.length} pages`);
